import { FadeUp } from './Reveal';
import ABOUT_IMG from '@/assets/about-poster.jpg';

const chapters = [
  {
    no: '01',
    title: 'The Origin',
    body: 'Stupid Studios began as a few friends with one borrowed camera and too many ideas. Every film is self-written, self-shot and self-directed — no studio, no shortcuts.',
  },
  {
    no: '02',
    title: 'The Craft',
    body: 'From taut thrillers like Thani Kaattu Raja to tender romances like Aval Naan Mazhai, we chase mood over budget — lighting, silence and performance doing the heavy lifting.',
  },
  {
    no: '03',
    title: 'The Mission',
    body: 'Prove that a compelling story shot on the streets of Tamil Nadu can move an audience just as hard as anything on the big screen. 28 films in, we are just getting started.',
  },
];

export const About = () => {
  return (
    <section id="about" className="relative px-6 md:px-12 py-28 md:py-40">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-16">
        <div className="lg:col-span-5 lg:sticky lg:top-32 self-start">
          <FadeUp>
            <span className="text-[11px] tracking-[0.3em] uppercase text-[#E11D48]">[ About ]</span>
            <h2 className="font-display font-semibold text-5xl md:text-7xl uppercase leading-[0.95] mt-5">
              Story<br />first.<br />Always.
            </h2>
          </FadeUp>
          <FadeUp delay={0.15}>
            <div className="mt-10 relative overflow-hidden group max-w-sm">
              <img
                src={ABOUT_IMG}
                alt="Founder of Stupid Studios — stay focused"
                className="w-full h-[460px] object-cover object-top transition-transform duration-700 group-hover:scale-105"
              />
              <div className="absolute inset-0 border border-white/10" />
            </div>
          </FadeUp>
        </div>

        <div className="lg:col-span-6 lg:col-start-7 flex flex-col gap-16 lg:pt-10">
          {chapters.map((c, i) => (
            <FadeUp key={c.no} delay={i * 0.1}>
              <div className="border-t border-white/10 pt-8">
                <div className="flex items-baseline gap-6">
                  <span className="font-display text-[#E11D48] text-lg">{c.no}</span>
                  <h3 className="font-display font-medium text-2xl md:text-3xl uppercase">
                    {c.title}
                  </h3>
                </div>
                <p className="mt-5 text-white/60 leading-relaxed text-base max-w-xl md:pl-12">
                  {c.body}
                </p>
              </div>
            </FadeUp>
          ))}
        </div>
      </div>
    </section>
  );
};
